-- V053: data_render card view — one card per row, cardsPerRow (default 1, max 6).

UPDATE dbo.AppAgentLibraryTool
SET
    ToolDescription = N'Present data in Agent Chat as an interactive UI panel. Non-blocking. ui=grid|card|chart|kpi_dashboard.
For KPI / dashboard / analysis / analyze / overview / summary requests: prefer ONE call with ui=kpi_dashboard and blocksJson (array). Model chooses how many markdown/kpi/chart/grid/card blocks (limits: kpi items<=12, chart blocks<=9, grid blocks<=3). Panel actionsJson and per-block actions allowed. Short FinalResponse text OK in addition to dashboard narrative. Single table/chart may still use ui=grid|chart.
ui=card renders one card per result row (pass the full JSON array, or dataset_name). Default is 1 card per row, filling the row. Pass cardsPerRow (1-6) when the user asks for several cards on one row.
Pass rows as dataJson for grid/card/chart. For kpi_dashboard pass blocksJson: [{type,id?,title?,content?,items?,data?,columns?,chartConfig?,actions?,meta?}]. type=markdown|kpi|chart|grid|card.',
    ParameterSchemaJson = N'{"ui":{"type":"string","description":"grid | card | chart | kpi_dashboard","required":true},"title":{"type":"string","description":"Optional panel title"},"dataJson":{"type":"string","description":"Required for grid/card/chart. JSON array of rows (card: one card per row) or one card object. For kpi_dashboard optional summary / blocks fallback."},"blocksJson":{"type":"string","description":"Required for kpi_dashboard. JSON array of blocks: markdown|kpi|chart|grid|card. kpi.items[{label,value,hint}], chart/grid use data+chartConfig/columns, optional per-block actions[{id,label}]. Card block meta.cardsPerRow is 1-6."},"columnsJson":{"type":"string","description":"Optional grid columns [{field,header,dataType,width,hide}]"},"chartConfigJson":{"type":"string","description":"Optional chart config {type,xField,yField,groupBy,allowedTypes}"},"actionsJson":{"type":"string","description":"Optional panel toolbar actions [{id,label}]"},"metaJson":{"type":"string","description":"Optional meta {subtitle,measure,total,cardsPerRow}. cardsPerRow 1-6, default 1."},"cardsPerRow":{"type":"integer","description":"Card view only. How many cards share one row. Default 1 (one card fills the row). Max 6."}}'
WHERE LibraryKey = N'data-ui-render'
  AND ToolName = N'data_render';
GO

UPDATE dbo.AppAgentToolRegister
SET
    ToolDescription = N'Present data in Agent Chat as an interactive UI panel. Non-blocking. ui=grid|card|chart|kpi_dashboard.
For KPI / dashboard / analysis / analyze / overview / summary requests: prefer ONE call with ui=kpi_dashboard and blocksJson (array). Model chooses how many markdown/kpi/chart/grid/card blocks (limits: kpi items<=12, chart blocks<=9, grid blocks<=3). Panel actionsJson and per-block actions allowed. Short FinalResponse text OK in addition to dashboard narrative. Single table/chart may still use ui=grid|chart.
ui=card renders one card per result row (pass the full JSON array, or dataset_name). Default is 1 card per row, filling the row. Pass cardsPerRow (1-6) when the user asks for several cards on one row.
Pass rows as dataJson for grid/card/chart. For kpi_dashboard pass blocksJson: [{type,id?,title?,content?,items?,data?,columns?,chartConfig?,actions?,meta?}]. type=markdown|kpi|chart|grid|card.',
    ParameterSchemaJson = N'{"ui":{"type":"string","description":"grid | card | chart | kpi_dashboard","required":true},"title":{"type":"string","description":"Optional panel title"},"dataJson":{"type":"string","description":"Required for grid/card/chart. JSON array of rows (card: one card per row) or one card object. For kpi_dashboard optional summary / blocks fallback."},"blocksJson":{"type":"string","description":"Required for kpi_dashboard. JSON array of blocks: markdown|kpi|chart|grid|card. kpi.items[{label,value,hint}], chart/grid use data+chartConfig/columns, optional per-block actions[{id,label}]. Card block meta.cardsPerRow is 1-6."},"columnsJson":{"type":"string","description":"Optional grid columns [{field,header,dataType,width,hide}]"},"chartConfigJson":{"type":"string","description":"Optional chart config {type,xField,yField,groupBy,allowedTypes}"},"actionsJson":{"type":"string","description":"Optional panel toolbar actions [{id,label}]"},"metaJson":{"type":"string","description":"Optional meta {subtitle,measure,total,cardsPerRow}. cardsPerRow 1-6, default 1."},"cardsPerRow":{"type":"integer","description":"Card view only. How many cards share one row. Default 1 (one card fills the row). Max 6."}}'
WHERE ToolName = N'data_render'
